code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                blocks.append((r, c))
    for top, left in blocks:
        spots = {
            'tl': (top - 1, left - 1),
            'tr': (top - 1, left + 2),
            'bl': (top + 2, left - 1),
            'br': (top + 2, left + 2),
        }
        vals = {key: grid[r][c] for key, (r, c) in spots.items()}
        moved = {'tl': vals['bl'], 'tr': vals['tl'], 'br': vals['tr'], 'bl': vals['br']}
        directions = {'tl': (-1, -1), 'tr': (-1, 1), 'bl': (1, -1), 'br': (1, 1)}
        for key, (r, c) in spots.items():
            dr, dc = directions[key]
            rr, cc = r, c
            while 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = moved[key]
                rr += dr
                cc += dc
    return out
'''
